from lit_prose import *


def exam(p):
    ch = p.chapter("ch-exam", "Answering in the exam: context questions, essays and unseen texts", "O Level Literature in English — answering context questions, writing essays on a text, unseen appreciation (transferable skills)")

    B(ch, slug="context-questions", title="Answering context (passage-based) questions", min=28,
      obj=["Read the command word and the marks of each question.", "Answer with point + short quotation + explanation.", "Place the passage in its wider story when asked."],
      notes=["The mark allocation of the sample questions is an illustration; the real distribution depends on the Board's paper."],
      blocks=[
          ("text", "**The Ferry**\nThe ferry shuddered away from the bank. Mbah gripped the rail with both hands and watched the shore shrink until it was no bigger than his mother's face at the doorway that morning. \"Write to us,\" she had said, pressing a bundle of cassava leaves into his arms as if they were a letter already. Now the bundle was damp with spray, and he held it like a heart he did not know how to keep from breaking."),
          ("fig", flow("Answering a context question", ["1 Read the passage twice", "2 Underline the command word and the marks", "3 Find the lines that answer the question", "4 Point + short quotation + explanation", "5 Check: does it match the marks?"], h=270),
           "One mark usually means one clear point.", "A vertical flow of five steps: read the passage twice, underline the command word and the marks, find the lines that answer, write point plus quotation plus explanation, check the answer against the marks."),
          ("key", "definition", "Command words",
           "- **State / Identify / Name:** a short, direct answer (one phrase).\n- **Explain / Why:** give the **reason** (because…).\n- **Describe:** say what something is like, with details.\n- **What does … suggest / show?** make an **inference** with evidence.\n- **How does the writer…? / Comment on…:** name the **technique**, **quote**, explain the **effect**.\n- **Compare:** similarities **and** differences."),
          ("key", "methode", "Marks and length",
           "- 1–2 marks: one or two lines. 3–4 marks: a short paragraph with **2–3 clear points**.\n- **Quote** only the few words you need, in quotation marks.\n- **Answer in your own words** first, then support with the quotation.\n- Use a **new sentence for each point**.\n- If the question says *in what way does this passage reveal…*, link the extract to the **theme or character** you know from the whole text."),
          ("key", "pieges", "Common mistakes",
           "- Copying a **long** quotation instead of commenting.\n- Answering with the **plot** (what happens) when the question is *how* or *why*.\n- Giving **one** point for a 4-mark question.\n- Ignoring the **marks**: a 2-mark question does not need a page.\n- Forgetting to **use evidence** for an inference (*he is sad* is not enough)."),
          ("ex", "Example 1: *the shore shrinks to his mother's face*", "(2 marks) What does *until it was no bigger than his mother's face at the doorway* suggest about Mbah's feelings?",
           ["Point 1: he is thinking of his mother as the shore gets smaller: the distance from home grows.", "Point 2: the comparison to a face shows love and homesickness."], "He is homesick: as the shore shrinks, his sadness at leaving his mother grows."),
          ("ex", "Example 2: *a heart he did not know how to keep from breaking*", "(3 marks) How does the writer show Mbah's feelings in the last sentence?",
           ["Device: a **simile**: the damp bundle is like a heart. Quote: *like a heart…*.", "Effect: the bundle from his mother stands for his love and his fear, and *breaking* shows that he is close to tears. He holds it carefully, as something precious."], "A simile shows the bundle as a fragile heart: he is sad, fears losing home, and treasures his mother's gift."),
      ],
      ex=[
          ("mcq", "A question beginning *State…* usually needs...", "a short, direct answer", ["a long paragraph", "a poem", "a quotation of the whole passage"], "State = say it briefly."),
          ("mcq", "How many separate points should you give for a question worth 3 marks?", "about three", ["one", "ten", "none"], "Roughly one point per mark."),
          ("tf", "When you quote, you should copy the whole paragraph to be safe.", False, "Use only the few words that prove your point."),
          ("mcq", "*Why did Mbah's mother press cassava leaves into his arms?* Which answer is best?", "She wanted him to carry a piece of home and food with him.", ["She was angry with him.", "She sold them at the market.", "The ferry was late."], "It shows care: the gift stands for home."),
          ("mcq", "*How does the writer…?* means you must...", "name a technique, quote and explain its effect", ["retell the plot", "give your own opinion only", "copy the next paragraph"], "Technique, quotation, effect."),
          ("problem", "Read: *Ada folded the exam results into a square so small that it vanished in her fist. The whole way home the road seemed to stretch, and every dog barked at her alone. At the gate she stopped, took a breath as deep as a well, and opened it.*", [
              part_mcq("(1 mark) What did Ada have in her hand?", "Her exam results", ["A letter from a friend", "A ticket", "A small stone"], "The first sentence says it."),
              part_mcq("(1 mark) *The road seemed to stretch* suggests that Ada...", "was afraid of arriving home", ["was running", "was lost", "enjoyed the walk"], "Time seems long when we dread something."),
              part_open("(2 marks) How does the writer create a sense of Ada's fear? Quote and explain.", "The writer uses personification (*every dog barked at her alone*) which makes the world seem hostile to her, and the verb *folded… so small that it vanished* shows she wants to hide the results. Both show that she is afraid of her parents' reaction.", ["1 mark: a device or detail with quotation.", "1 mark: explained effect on the reader."])]),
      ],
      sc=[("*Explain why…* needs...", "a reason", ["a list of names", "a quotation only", "a rhyme"], "Because…"),
          ("In a comment you should quote...", "only a few words", ["the whole page", "nothing", "the title only"], "Short quotation."),
          ("A 4-mark question needs about...", "four clear points", ["one word", "ten pages", "a drawing"], "Match answer to marks."),
          ("What is the first step?", "read the passage carefully", ["write the answer", "close the paper", "count the lines"], "Read twice."),
          ("An inference answer must include...", "evidence from the text", ["a guess", "personal gossip", "a definition"], "Evidence supports inference.")])

    B(ch, slug="essay-on-text", title="Writing an essay on a text: Point–Evidence–Explain", min=28,
      obj=["Plan an essay: introduction, three body paragraphs, conclusion.", "Write PEEL paragraphs with short quotations.", "Keep to the question and avoid retelling the story."],
      pre=["gceol-literature-plot-setting-theme"],
      notes=["The model essay uses the original mini-story The Last Mango from the first lesson of this pack. In class, the teacher should replace it with the official set texts."],
      blocks=[
          ("fig", flow("PEEL: building a paragraph", ["P — Point: answer the question directly", "E — Evidence: a short quotation or detail", "E — Explain: how the evidence proves the point", "L — Link back to the question"], h=215),
           "Each body paragraph follows the same four steps.", "Four boxes joined by arrows: Point, Evidence, Explain, Link."),
          ("key", "methode", "Planning the essay",
           "Question: *How does the writer present Nkem's pride in The Last Mango?*\n1. **Introduction:** answer the question in 2–3 sentences (the main idea).\n2. **Paragraph 1:** pride in his **action** (he lifts his chin).\n3. **Paragraph 2:** pride in his **thoughts** (the voice of his grandmother).\n4. **Paragraph 3:** the **contrast** with his poverty (the coins).\n5. **Conclusion:** sum up and give a final comment on the writer's purpose."),
          ("key", "definition", "A model PEEL paragraph",
           "*The writer shows Nkem's pride in his body language* (**P**). *After the bell he « lifted his chin and walked into class as if he owned the whole world »* (**E**). *The phrase « as if » shows that he is pretending to be rich, and the raised chin shows that he refuses to let others see his poverty* (**E**). *So his pride is a protection against shame* (**L**)."),
          ("key", "retenir", "Types of essay question",
           "- **Character:** *How does the writer present…?*\n- **Theme:** *Discuss the theme of…*\n- **Setting / mood:** *What part does the setting play…?*\n- **Technique:** *How does the writer use imagery / irony…?*\n- **Opinion:** *To what extent do you agree that…?* → state your view and give reasons.\nAlways write about **the writer's choices**, not just the story."),
          ("key", "pieges", "Common mistakes",
           "- **Retelling** the story instead of answering.\n- Quotations that are **too long** or **unexplained**.\n- No clear **introduction** or **conclusion**.\n- Writing about a different character or theme than the one asked.\n- Weak vocabulary: repeating *the writer shows*; try *suggests, reveals, emphasises, creates*."),
          ("ex", "Example 1: the introduction", "Write an introduction (2–3 sentences) for the essay on Nkem's pride.",
           ["Start by answering: Nkem's pride is shown through…", "Mention the main ideas (action, thought, contrast with poverty) without developing them."], "In The Last Mango, the writer presents Nkem's pride through his actions, his thoughts and the contrast with his poverty. His pride helps him face disappointment, but it also hides how much he needs."),
          ("ex", "Example 2: spotting a weak paragraph", "Why is this paragraph weak? *Nkem has 250 francs. He looks at the tree. The bell rings. He goes to class.*",
           ["It only retells events (no point, no evidence, no explanation).", "A good paragraph states a point and **explains** how the writer's words show it."], "It retells the story and has no analysis."),
      ],
      ex=[
          ("mcq", "In PEEL, the first E stands for...", "Evidence", ["Ending", "Essay", "Example only"], "P = Point, E = Evidence, E = Explain, L = Link."),
          ("mcq", "Which is the best Point sentence for a paragraph on Nkem's pride?", "The writer shows Nkem's pride in his body language.", ["Nkem is a boy.", "Next, the bell rang.", "I like the story."], "A point answers the question."),
          ("tf", "A literature essay should mainly retell the story.", False, "It should analyse the writer's choices."),
          ("mcq", "Which quotation is the best evidence?", "\"lifted his chin\"", ["the whole first paragraph", "\"Nkem\"", "\"The bell rang. He pushed the coins deep into his pocket, lifted his chin and walked into class as if he owned the whole world.\" and then more"], "Short and precise."),
          ("mcq", "The Link sentence should...", "return to the question", ["start a new topic", "give the page number", "repeat the quotation"], "It ties the paragraph to the question."),
          ("open", "Write **one PEEL paragraph** (about 80 words) answering: *How does the narrator show guilt in The Lamp?* (Story: the narrator hides the broken lamp from Mama: *I told myself it was kindness… I knew that she had known all along.*)",
           "The writer shows the narrator's guilt through his excuses. He says, *I told myself it was kindness*, which shows that he is trying to justify his silence. The words *told myself* suggest that he does not really believe the excuse, so we understand that he feels ashamed. This ending, when he realises that Mama *had known all along*, makes his guilt more painful.",
           ["1 mark: a clear point.", "1 mark: a short quotation.", "1 mark: explanation of the effect or meaning.", "1 mark: a link to the question; correct English; about 80 words."]),
      ],
      sc=[("PEEL stands for...", "Point, Evidence, Explain, Link", ["Poem, Essay, Edit, Learn", "Plot, End, Event, Line", "Pen, Exam, Eye, Love"], "A paragraph structure."),
          ("A conclusion should...", "sum up the answer", ["add a new topic", "retell the plot", "be omitted"], "Sum up."),
          ("An introduction should...", "answer the question briefly", ["tell the whole story", "list all quotations", "ask the examiner a question"], "Give the main idea."),
          ("Quotations should be...", "short and explained", ["very long", "without comment", "invented"], "Short, precise, explained."),
          ("If the question asks about a theme, you write about...", "the theme in the writer's choices", ["a different text", "your holidays", "the author's age"], "Stay on the question.")])

    B(ch, slug="unseen-appreciation", title="Unseen poetry and prose: appreciation", min=28,
      obj=["Read an unseen text with a clear method.", "Describe the speaker, situation, tone and theme.", "Comment on devices and structure and give a personal response."],
      notes=["The unseen poem is original. Different readers may interpret some images differently: answers must be accepted if supported by the text."],
      blocks=[
          ("text", "**The Letter**\nMother's letters come on thin blue paper,\nfolded small as a secret.\nI read them in the shade of the mango tree,\nmy thumb across her careful handwriting\nas if I could touch her hand.\nShe writes of rain, of cousins, of the price of fish.\nShe never writes: *I miss you.*\nBut every page smells of woodsmoke,\nand the last line always says: *Eat well.*"),
          ("fig", flow("A method for unseen texts", ["1 Read three times; think about the title", "2 Who speaks? To whom? What situation?", "3 Tone and any shift in mood", "4 Devices and their effects", "5 Structure, form and sound", "6 Your own response, with evidence"], h=315),
           "Make brief notes under each heading before writing.", "A vertical chain of six boxes: read three times and think about the title; who speaks, to whom, in what situation; tone and shifts; devices and effects; structure, form and sound; your personal response with evidence."),
          ("key", "methode", "Reading the poem",
           "- **Speaker and situation:** a young person, away from home, reading letters from his or her mother.\n- **Tone:** tender and wistful (full of longing).\n- **Theme:** love shown indirectly, through small details.\n- **Turn:** the line *She never writes: I miss you. / But…* changes the focus from what is missing to what the letters really show."),
          ("key", "methode", "Devices and structure",
           "- **Simile:** *folded small as a secret* suggests that the letters are precious and private.\n- **Imagery:** touch (*my thumb across… handwriting*) and smell (*woodsmoke*) bring the mother's presence.\n- **Plain language and a list:** *rain, cousins, the price of fish* show everyday life.\n- **Form:** free verse; no rhyme, like quiet speech. **Ending:** *Eat well* is a command that hides love."),
          ("key", "pieges", "Common mistakes",
           "- Saying *I don't understand it* and writing nothing: describe **what you do see**.\n- Looking for **one** correct interpretation: a reasoned reading is accepted.\n- Listing devices without effects.\n- Ignoring the **title** and the **ending**.\n- Forgetting your **personal response** (*I found the poem moving because…*)."),
          ("ex", "Example 1: tone and evidence", "What is the tone of *The Letter*? Give evidence.",
           ["Tone words: tender, wistful. Evidence: *my thumb across her careful handwriting / as if I could touch her hand*.", "The speaker misses his or her mother but speaks gently, without complaint."], "Tender and wistful: the speaker touches the handwriting as if touching the mother's hand."),
          ("ex", "Example 2: the last line", "What is the effect of ending with *Eat well*?",
           ["It is a simple, everyday command from a mother: practical, not emotional.", "The reader senses that her love hides inside ordinary advice, so the ending is moving."], "The ordinary advice hides her deep love, so the poem ends with quiet emotion."),
      ],
      ex=[
          ("mcq", "The main theme of *The Letter* is...", "love expressed through small details", ["hatred of school", "a journey by sea", "the price of fish"], "The speaker recognises love in the details of the letters."),
          ("mcq", "*folded small as a secret* is a...", "simile", ["metaphor", "irony", "onomatopoeia"], "It compares using *as*."),
          ("tf", "The poem is written in regular rhyming couplets.", False, "It is free verse: no regular rhyme."),
          ("mcq", "Which sense does the line *every page smells of woodsmoke* use?", "smell", ["sight", "taste", "hearing"], "Smell brings back home."),
          ("mcq", "Why does the speaker mention *the price of fish*?", "It shows that the mother writes about ordinary life.", ["The speaker wants to buy fish.", "The poem is about fishing.", "It rhymes with the next line."], "Ordinary details suggest her love is hidden inside daily life."),
          ("open", "Read: *The old drum sleeps behind the chief's house, / its skin cracked like a dry river bed. / Children run past without a glance. / But on moonlit nights the elders whisper / that it dreams of festivals, / and the ground trembles a little in answer.*\nWrite a short appreciation (about 100 words): theme, tone and two devices.",
           "The poem is about a forgotten tradition that is not quite dead. The tone is quiet and nostalgic, with a little hope at the end. The personification of the drum, which *sleeps* and *dreams*, makes it seem alive, and the simile *cracked like a dry river bed* shows how old and neglected it is. The last line, where the ground *trembles a little*, suggests that the community's memory still responds, so the old culture can wake up again.",
           ["1 mark: theme stated (tradition forgotten, still alive).", "1 mark: tone with evidence.", "1 mark: first device with quotation and effect.", "1 mark: second device, or a link between devices and theme; correct English."]),
      ],
      sc=[("The first thing to do with an unseen poem is...", "read it several times", ["write the essay", "count the letters", "skip it"], "Read three times."),
          ("Free verse...", "does not use a regular rhyme scheme", ["always rhymes", "has 14 lines", "has no words"], "No fixed pattern."),
          ("A personal response should be...", "supported by evidence", ["unrelated", "only a feeling", "copied"], "Give reasons from the text."),
          ("The tone of *The Letter* is best described as...", "tender", ["furious", "bored", "mocking"], "Gentle and loving."),
          ("The title *The Letter* is important because...", "the whole poem centres on the letters", ["it is a rhyme", "it is long", "it has no meaning"], "Always consider the title.")])
    return ch
